function getCardBackgroundImage(name, isTab) {
  if (!name) return "";
  var clean = name.toLowerCase().replace(/\s+/g, "-").replace(/[^a-z0-9\-&]/g, "");
  var cleanWithAnd = clean.replace(/&/g, "and");
  var cleanWithAmp = clean.replace(/and/g, "&");

  var candidates = isTab
    ? [
        "tab-" + clean,
        "tab-" + cleanWithAnd,
        "tab-" + cleanWithAmp,
        clean,
        cleanWithAnd,
        cleanWithAmp
      ]
    : [
        clean,
        cleanWithAnd,
        cleanWithAmp
      ];

  for (var i = 0; i < candidates.length; i++) {
    var key = candidates[i];
    if (CARD_BACKGROUND_DATA_URIS[key]) {
      return CARD_BACKGROUND_DATA_URIS[key];
    }
  }

  return CARD_BACKGROUND_DATA_URIS["on-going-opportunities"] || "";
}

if (typeof window !== "undefined") {
  window.CARD_BACKGROUND_SVGS = CARD_BACKGROUND_SVGS;
  window.CARD_BACKGROUND_DATA_URIS = CARD_BACKGROUND_DATA_URIS;
  window.getCardBackgroundImage = getCardBackgroundImage;
}

if (typeof module !== "undefined") {
  module.exports = {
    CARD_BACKGROUND_SVGS: CARD_BACKGROUND_SVGS,
    CARD_BACKGROUND_DATA_URIS: CARD_BACKGROUND_DATA_URIS,
    getCardBackgroundImage: getCardBackgroundImage
  };
}
